import { useEffect, useRef, useState } from 'react';

import { Alert } from 'components';

import {
  StyledBrandPowerContextBanner,
  StyledBrandPowerContextBannerMessage,
} from './BrandPowerContextBanner.styles';

export interface BrandPowerContextBannerProps {
  title?: string;
  message: string;
  duration?: number;
}

export const DEFAULT_BRAND_POWER_CONTEXT_BANNER_DURATION = 6000;
export const BRAND_POWER_CONTEXT_BANNER_FADE_OUT_DURATION = 300;

export const BrandPowerContextBanner: React.FC<
  BrandPowerContextBannerProps
> = ({
  title,
  message,
  duration = DEFAULT_BRAND_POWER_CONTEXT_BANNER_DURATION,
}) => {
  const [closing, setClosing] = useState(false);
  const [hidden, setHidden] = useState(false);

  const dismissTimerRef = useRef<ReturnType<typeof setTimeout>>();
  const hideTimerRef = useRef<ReturnType<typeof setTimeout>>();

  useEffect(() => {
    if (duration <= 0) return;

    dismissTimerRef.current = setTimeout(() => {
      setClosing(true);
      hideTimerRef.current = setTimeout(
        () => setHidden(true),
        BRAND_POWER_CONTEXT_BANNER_FADE_OUT_DURATION,
      );
    }, duration);

    return () => {
      clearTimeout(dismissTimerRef.current);
      clearTimeout(hideTimerRef.current);
    };
  }, [duration]);

  if (hidden) return null;

  return (
    <StyledBrandPowerContextBanner closing={closing}>
      <Alert
        type="info"
        position="inline"
        title={title}
        message={
          <StyledBrandPowerContextBannerMessage>
            {message}
          </StyledBrandPowerContextBannerMessage>
        }
      />
    </StyledBrandPowerContextBanner>
  );
};

BrandPowerContextBanner.displayName = 'BrandPowerContextBanner';
